@app.post("/themes")
@login_required
def upload_theme(req):
    f = req.files["archive"]
    if not f.filename.endswith(".tar.gz"):
        abort(400)
    dest = os.path.join(THEMES_DIR, str(req.user.id))
    with tarfile.open(fileobj=f.stream, mode="r:gz") as tar:
        tar.extractall(dest)
    return {"ok": True}
